function bytesFromBase64(data:string){
 const clean=data.replace(/\s+/g,'');
 const binary=atob(clean);
 const bytes=new Uint8Array(binary.length);
 for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
 return bytes;
}

const heightBytes=bytesFromBase64(HEIGHT_B64);
const heights=new Uint16Array(
 heightBytes.buffer,
 heightBytes.byteOffset,
 heightBytes.byteLength/Uint16Array.BYTES_PER_ELEMENT,
);

const treeBytes=bytesFromBase64(TREE_B64);
const trees=new Float32Array(
 treeBytes.buffer,
 treeBytes.byteOffset,
 treeBytes.byteLength/Float32Array.BYTES_PER_ELEMENT,
);

const grid=new Map<number,number[]>();
const cellSize=XIANXIA_MAP.collisionCell;
const cellKey=(cx:number,cz:number)=>((cx+64)<<8)|(cz+64);

function addToGrid(index:number,x:number,z:number,hw:number,hd:number){
 const minCx=Math.floor((x-hw)/cellSize),maxCx=Math.floor((x+hw)/cellSize);
 const minCz=Math.floor((z-hd)/cellSize),maxCz=Math.floor((z+hd)/cellSize);
 for(let cx=minCx;cx<=maxCx;cx++)for(let cz=minCz;cz<=maxCz;cz++){
  const key=cellKey(cx,cz),bucket=grid.get(key);
  if(bucket)bucket.push(index);else grid.set(key,[index]);
 }
}
for(let i=0;i<XIANXIA_MAP.treeColliders;i++){
 const o=i*4;
 addToGrid(i,trees[o],trees[o+1],trees[o+2],trees[o+3]);
}

function sampleHeightIndex(ix:number,iz:number){
 return XIANXIA_MAP.heightBase+heights[ix*XIANXIA_MAP.rows+iz]*XIANXIA_MAP.heightScale;
}

/** Bilinear height sampling from the exact uploaded Terrain mesh. */
export function xianxiaHeightAt(x:number,z:number){
 const fx=Math.max(0,Math.min(XIANXIA_MAP.columns-1,(x-XIANXIA_MAP.minX)/XIANXIA_MAP.step));
 const fz=Math.max(0,Math.min(XIANXIA_MAP.rows-1,(z-XIANXIA_MAP.minZ)/XIANXIA_MAP.step));
 const x0=Math.floor(fx),z0=Math.floor(fz),x1=Math.min(XIANXIA_MAP.columns-1,x0+1),z1=Math.min(XIANXIA_MAP.rows-1,z0+1);
 const tx=fx-x0,tz=fz-z0;
 const h00=sampleHeightIndex(x0,z0),h10=sampleHeightIndex(x1,z0),h01=sampleHeightIndex(x0,z1),h11=sampleHeightIndex(x1,z1);
 const a=h00+(h10-h00)*tx,b=h01+(h11-h01)*tx;
 return a+(b-a)*tz;
}

/** Zero-allocation point query used by the server movement loop. */
export function xianxiaTreeBlocked(p:Vec2,margin=.55){
 const minCx=Math.floor((p.x-margin)/cellSize),maxCx=Math.floor((p.x+margin)/cellSize);
 const minCz=Math.floor((p.z-margin)/cellSize),maxCz=Math.floor((p.z+margin)/cellSize);
 for(let cx=minCx;cx<=maxCx;cx++)for(let cz=minCz;cz<=maxCz;cz++){
  const bucket=grid.get(cellKey(cx,cz));if(!bucket)continue;
  for(const i of bucket){
   const o=i*4,x=trees[o],z=trees[o+1],hw=trees[o+2]+margin,hd=trees[o+3]+margin;
   if(Math.abs(p.x-x)<=hw&&Math.abs(p.z-z)<=hd)return true;
  }
 }
 return false;
}

function nearbyTreeIndices(minX:number,maxX:number,minZ:number,maxZ:number){
 const result:number[]=[];const seen=new Set<number>();
 const minCx=Math.floor(minX/cellSize),maxCx=Math.floor(maxX/cellSize);
 const minCz=Math.floor(minZ/cellSize),maxCz=Math.floor(maxZ/cellSize);
 for(let cx=minCx;cx<=maxCx;cx++)for(let cz=minCz;cz<=maxCz;cz++){
  const bucket=grid.get(cellKey(cx,cz));if(!bucket)continue;
  for(const i of bucket)if(!seen.has(i)){seen.add(i);result.push(i);}
 }
 return result;
}

/** Conservative cell test used when building the A* navigation mesh. */
export function xianxiaAreaClear(minX:number,maxX:number,minZ:number,maxZ:number,margin=.55){
 const ids=nearbyTreeIndices(minX-margin,maxX+margin,minZ-margin,maxZ+margin);
 for(const i of ids){
  const o=i*4,x=trees[o],z=trees[o+1],hw=trees[o+2]+margin,hd=trees[o+3]+margin;
  if(x+hw>=minX&&x-hw<=maxX&&z+hd>=minZ&&z-hd<=maxZ)return false;
 }
 return true;
}

export function xianxiaMapWalkable(p:Vec2,margin=.55){
 if(p.x<=XIANXIA_MAP.playableMin+margin||p.x>=XIANXIA_MAP.playableMax-margin||p.z<=XIANXIA_MAP.playableMin+margin||p.z>=XIANXIA_MAP.playableMax-margin)return false;
 return !xianxiaTreeBlocked(p,margin);
}

/** Zero-allocation iteration for client-side camera collision proxies. */
export function forEachXianxiaTreeCollider(fn:(x:number,z:number,halfWidth:number,halfDepth:number,index:number)=>void){
 for(let i=0;i<XIANXIA_MAP.treeColliders;i++){const o=i*4;fn(trees[o],trees[o+1],trees[o+2],trees[o+3],i);}
}
